<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, reactive, ref } from 'vue';
import { api, ApiError, errorText, mutationId, session } from '../../../frontend/src/api';
import type { PhotoInput } from '../../../packages/contracts/src/index.js';
import type { AdminPhotoDetail } from '../../../packages/contracts/src/admin.js';
import type { PlaceResult } from '../../../frontend/src/maps/placeSearch';
import { searchPlaces } from '../../../frontend/src/maps/placeSearch';
import { loadAtlasCatalog } from '../../../frontend/src/atlasCatalog';
import ModalSheet from '../../../frontend/src/components/ModalSheet.vue';
import Icon from './AdminIcon.vue';
const props=defineProps<{id:string}>(),emit=defineEmits<{close:[];saved:[]}>();
const detail=ref<AdminPhotoDetail>(),loading=ref(true),busy=ref(false),error=ref(''),imageError=ref(false),searching=ref(false),finding=ref(false),searchError=ref(''),results=ref<PlaceResult[]>([]),keyword=ref(''),city=ref('');
const draft=reactive<PhotoInput>({mediaId:props.id,baseVersion:0,takenOn:null,place:null,note:''});
let baseline='',disposed=false,searchGeneration=0;
const pending=ref<(PhotoInput&{clientMutationId:string})|null>(null),dirty=computed(()=>baseline!==''&&JSON.stringify(draft)!==baseline),locked=computed(()=>busy.value||!!pending.value||!!detail.value?.hidden);
async function load(){loading.value=true;error.value='';resetResults();try{const value=await api<AdminPhotoDetail>('/admin/photos/'+props.id);if(disposed)return;detail.value=value;Object.assign(draft,{mediaId:value.mediaId,baseVersion:value.baseVersion,takenOn:value.takenOn,place:value.place,note:value.note});baseline=JSON.stringify(draft);city.value=value.place?.cityName??'';pending.value=null;searching.value=false;imageError.value=false;}catch(e){if(!disposed)error.value=errorText(e);}finally{if(!disposed)loading.value=false;}}
function close(){if(busy.value)return;if((dirty.value||pending.value)&&!window.confirm('放弃尚未确认保存的照片信息？'))return;emit('close');}
async function reload(){if((dirty.value||pending.value)&&!window.confirm('重新读取服务器内容，并放弃当前修改？'))return;await load();}
async function save(){if(!detail.value||detail.value.hidden||busy.value)return;busy.value=true;error.value='';pending.value??={...JSON.parse(JSON.stringify(draft)),clientMutationId:mutationId()};try{await api('/admin/photos/'+props.id,'PUT',pending.value);baseline=JSON.stringify(draft);pending.value=null;emit('saved');}catch(e){if(e instanceof ApiError&&e.status>=400&&e.status<500)pending.value=null;error.value=errorText(e);}finally{busy.value=false;}}
function resetResults(){searchGeneration++;results.value=[];finding.value=false;searchError.value='';}
async function find(){if(!keyword.value.trim())return;const current=++searchGeneration;finding.value=true;searchError.value='';results.value=[];try{const data=await searchPlaces(keyword.value.trim(),city.value.trim(),await loadAtlasCatalog());if(!disposed&&current===searchGeneration)results.value=data;}catch(e){if(!disposed&&current===searchGeneration)searchError.value=errorText(e);}finally{if(!disposed&&current===searchGeneration)finding.value=false;}}
function choose(place:PlaceResult){draft.place={label:place.name.slice(0,100),cityName:place.city.slice(0,80),...(place.place?.countryCode==='CHN'?{cityCode:place.place.areaCode}:{}),position:place.location,source:place.location?'map':'manual'};searching.value=false;results.value=[];searchGeneration++;finding.value=false;}
function useCapturePosition(){if(!detail.value?.capture?.position)return;draft.place={label:draft.place?.label??'照片拍摄地点',cityName:draft.place?.cityName??'',position:detail.value.capture.position,source:'exif'};}
function unload(event:BeforeUnloadEvent){if(dirty.value||pending.value){event.preventDefault();event.returnValue='';}}
onMounted(()=>{void load();window.addEventListener('beforeunload',unload);});onBeforeUnmount(()=>{disposed=true;searchGeneration++;window.removeEventListener('beforeunload',unload);});
</script>
<template><ModalSheet class="photo-inspector-dialog" :title="searching?'选择照片拍摄地点':'整理照片'" :busy="busy" @close="close">
 <p v-if="loading" class="admin-message" role="status">正在读取照片信息…</p>
 <template v-else-if="detail">
  <template v-if="searching"><div class="photo-search-head"><button class="text-button" @click="searching=false">← 返回照片</button><span>选择拍摄时的位置</span></div><form class="photo-place-search" @submit.prevent="find"><div class="flow-field"><label for="photo-search-city">搜索范围（可留空）</label><input id="photo-search-city" v-model="city" @input="resetResults" maxlength="80" placeholder="武汉市，留空搜索全国"></div><div class="flow-field"><label for="photo-search-query">地点名称</label><input id="photo-search-query" v-model="keyword" @input="resetResults" type="search" required maxlength="100" placeholder="景点、街道、客栈…"></div><button class="secondary-button" :disabled="finding||!keyword.trim()">{{ finding?'正在搜索…':'搜索地点' }}</button></form><p v-if="searchError" class="flow-form-errors" role="alert">{{ searchError }}</p><div class="photo-place-results"><button v-for="place in results" :key="place.id" @click="choose(place)"><Icon name="pin"/><span><strong>{{ place.name }}</strong><small>{{ place.city }} · {{ place.address }}</small></span><span>{{ place.location?'选择':'仅名称' }}</span></button></div><button v-if="keyword.trim()&&!finding" class="text-button manual-place" @click="choose({id:'manual',name:keyword.trim(),city:city.trim(),address:'',location:null})">仅记下“{{ keyword.trim() }}”，以后再补精确位置</button></template>
  <template v-else><figure class="photo-inspector-image"><img v-if="!imageError" :src="detail.previewUrl" :alt="detail.filename" @error="imageError=true"><p v-else>图片暂时未能加载。<button class="text-button" @click="imageError=false">重新加载</button></p></figure><div class="photo-caption"><strong>{{ detail.filename }}</strong><span>{{ detail.width }} × {{ detail.height }} · {{ detail.ownerName }}</span></div><p v-if="detail.hidden" class="detail-hint">这张照片已从回忆中隐藏，当前只供查看。</p><p v-else-if="detail.source==='upload'" class="detail-hint">这是尚未收录的上传，保存信息后会出现在照片回忆中。</p>
   <form id="admin-photo-form" @submit.prevent="save"><div class="flow-field"><label for="photo-taken-on">拍摄日期</label><input id="photo-taken-on" :value="draft.takenOn??''" type="date" :disabled="locked" @input="draft.takenOn=($event.target as HTMLInputElement).value||null"><button v-if="detail.capture?.takenOn" type="button" class="text-button" :disabled="locked" @click="draft.takenOn=detail.capture!.takenOn">采用原图日期 {{ detail.capture.takenOn }}</button></div><div class="flow-field"><label>拍摄地点</label><div class="photo-place-current"><Icon name="pin"/><div><strong>{{ draft.place?.label??'还没有拍摄地点' }}</strong><small>{{ draft.place?.position?'已有精确位置':draft.place?'只有地点名称，仍可补位置':'可通过搜索补充位置' }}</small></div><button type="button" class="text-button" :disabled="locked" @click="searching=true;keyword='';results=[];searchError=''">{{ draft.place?'更换':'选择地点' }}</button></div><div class="photo-field-actions"><button v-if="detail.capture?.position" type="button" class="text-button" :disabled="locked" @click="useCapturePosition">使用原图中的位置</button><button v-if="draft.place" type="button" class="text-button" :disabled="locked" @click="draft.place=null">清除地点</button></div></div><div class="flow-field"><label for="photo-note">简短备注</label><textarea id="photo-note" v-model="draft.note" :disabled="locked" maxlength="1000" rows="3" placeholder="给这张照片留一两句话…"></textarea><small>{{ draft.note.length }} / 1000</small></div></form>
   <div v-if="detail.diary" class="photo-related"><small>关联记录</small><strong>{{ detail.diary.title }}</strong><span v-if="detail.diary.stopLabel">{{ detail.diary.stopLabel }}</span><a v-if="detail.ownerId===session?.user.id" :href="'https://travel.yiqu.love/diaries/'+detail.diary.id" target="_blank" rel="noopener noreferrer">在使用端查看日记 ↗</a></div>
  </template>
 </template>
 <template #footer><p v-if="error&&!pending" class="flow-form-errors photo-footer-message" role="alert">{{ error }}</p><p v-if="pending&&!busy" class="photo-pending photo-footer-message" role="status">保存结果尚未确认，请重试同一次保存，或重新读取核对。</p><div class="photo-inspector-footer"><button class="secondary-button" :disabled="busy" @click="detail?reload():load()">重新读取</button><button v-if="!searching&&!detail?.hidden" class="primary" type="submit" form="admin-photo-form" :disabled="loading||busy||!detail||(!dirty&&!pending)">{{ busy?'正在保存…':pending?'重试保存':'保存照片信息' }}</button><button v-else class="primary" :disabled="busy" @click="searching?searching=false:close()">{{ searching?'返回照片':'关闭' }}</button></div></template>
</ModalSheet></template>
